INSERT INTO changelog (title, body, created_at) VALUES ('Проєкт: «Збережено ✓» і Clarity в будь-якому проєкті', 'Після «Зберегти» в «Робочому місці» проєкту тепер видно позначку «Збережено ✓» (раніше збереження працювало, але нічого не показувало). Якщо в проєкті вписаний Microsoft Clarity — на Огляді зʼявляється блок сайту з кнопками «Теплова карта» і «Записи сесій», навіть якщо проєкт не позначений як сайт.', datetime('now'));
